//! The Grok Shell icon set (`icons.tsx`): the SVG path data drawn through
//! `canvas()` + `svg_path` — no glyph fallbacks. The data below is generated
//! from `grok-shell/app/icons.tsx` (ICONS + BRANDS); edit there first.

use std::str::FromStr;

use nsh_core::canvas::{svg_path, FillRule, LineCap, LineJoin, Path};
use nsh_core::prelude::*;

use crate::theme;

/// One path of an icon: SVG data + how the TSX drew it (`s` stroked else
/// filled, `f` an explicit color else the icon ink, `w` the stroke width —
/// 0 is the TSX default of 2 — `r: "evenodd"` the fill rule).
#[derive(Default)]
pub(crate) struct IconPath {
    pub d: &'static str,
    pub f: Option<&'static str>,
    pub s: bool,
    pub w: f32,
    pub evenodd: bool,
}

/// An icon's viewBox and paths.
pub(crate) struct IconSpec {
    pub vb: [f32; 4],
    pub paths: &'static [IconPath],
}

/// A resolved paint op (path parsed once, explicit color decoded once).
enum Op {
    Fill(Path, Option<Hsla>, FillRule),
    Stroke(Path, Option<Hsla>, f32),
}

fn ops_of(spec: &IconSpec) -> Vec<Op> {
    spec.paths
        .iter()
        .map(|p| {
            let f = p.f.and_then(|f| Hsla::from_str(f).ok());
            if p.s {
                Op::Stroke(svg_path(p.d), f, if p.w > 0.0 { p.w } else { 2.0 })
            } else {
                Op::Fill(
                    svg_path(p.d),
                    f,
                    if p.evenodd {
                        FillRule::EvenOdd
                    } else {
                        FillRule::NonZero
                    },
                )
            }
        })
        .collect()
}

/// `Icon`'s draw: scale the viewBox to the canvas, round caps/joins, then
/// fill or stroke each path in `f ?? ink` (icons.tsx:155-168).
fn paint(vb: [f32; 4], ops: &[Op], w: f32, h: f32, ink: Hsla) -> Painter {
    let mut p = Painter::new()
        .scale(w / vb[2], h / vb[3])
        .translate(-vb[0], -vb[1])
        .line_cap(LineCap::Round)
        .line_join(LineJoin::Round);
    for op in ops {
        p = match op {
            Op::Fill(path, c, rule) => p.fill_style(c.unwrap_or(ink)).fill_path(path, *rule),
            Op::Stroke(path, c, lw) => p
                .stroke_style(c.unwrap_or(ink))
                .line_width(*lw)
                .stroke_path(path),
        };
    }
    p
}

/// `Icon` — a canvas icon by ICONS/alias name at the call site's usual size
/// (the TSX passes `size` per use; these defaults match it). Unknown names
/// draw nothing (the TSX's `!s` return); `"reply"` is the literal `↩` the
/// TSX `Act` renders as text, not an ICONS entry.
pub(crate) fn icon(name: &str) -> AnyElement {
    if name == "reply" {
        return text("↩")
            .text_size(px(15.0))
            .text_color(theme::DIM)
            .text_center()
            .into_element();
    }
    icon_sized(name, default_size(name))
}

/// `Icon` at an explicit size, default ink.
pub(crate) fn icon_sized(name: &str, size: f32) -> AnyElement {
    icon_ink(name, size, || theme::DIM)
}

/// `Icon` with an explicit ink (the send arrow's `sendInk`, badge close).
/// `ink` runs inside the painter so themed/bot inks stay reactive.
pub(crate) fn icon_ink(
    name: &str,
    size: f32,
    ink: impl Fn() -> AdaptiveColor + 'static,
) -> AnyElement {
    let (vb, ops) = spec(name)
        .map(|s| (s.vb, ops_of(&s)))
        .unwrap_or(([0.0; 4], Vec::new()));
    canvas(move || paint(vb, &ops, size, size, color(ink())))
        .size(px(size))
        .into_element()
}

/// The size each TSX call site passes (`size ?? 18` in `Icon`; the shell's
/// controls are mostly 13–16pt).
fn default_size(name: &str) -> f32 {
    match name {
        "close" | "check" | "tool" => 13.0,
        "chevronSmRight" | "chev-right" | "chevronSmDown" | "chev-down" | "caretDown" => 14.0,
        "panel" | "panelLeft" | "emojiPlus" | "smile" | "voice" => 18.0,
        "plus" | "attach" | "newChat" | "settings" | "arrowUpRight" | "sidebar" | "sidebarRail" => {
            16.0
        }
        _ => 15.0,
    }
}

/// `BRANDS[name]` — whether a brand glyph exists (the TSX `plugTile` falls
/// back to the hue letter tile otherwise).
pub(crate) fn has_brand(name: &str) -> bool {
    brand(name).is_some()
}

/// `BrandTile` — the white rounded tile with the brand glyph in the brand's
/// hex (icons.tsx:174).
pub(crate) fn brand_tile(name: &str, size: f32) -> AnyElement {
    let Some((hex, s)) = brand(name) else {
        return view().size(px(size)).into_element();
    };
    let g = size * 0.58;
    let fill = Hsla::from_str(hex).unwrap_or(theme::ACCENT.dark);
    let ops = fill_ops(&s);
    view()
        .size(px(size))
        .rounded(px(size * 0.25))
        .bg(Hsla::from_str("#ffffff").unwrap_or(fill))
        .border(px(0.5))
        .border_color(Hsla::from_str("#0000001a").unwrap_or(fill))
        .items_center()
        .justify_center()
        .child(canvas(move || fill_paths(s.vb, &ops, g, g, fill)).size(px(g)))
        .into_element()
}

/// `BrandChip` — the brand-colored tile with the glyph knocked out to ink
/// (white on dark brands, dark on light; icons.tsx:196).
pub(crate) fn brand_chip(name: &str, size: f32) -> AnyElement {
    let Some((hex, s)) = brand(name) else {
        return view().size(px(size)).into_element();
    };
    let g = size * 0.66;
    let fill = Hsla::from_str(hex).unwrap_or(theme::ACCENT.dark);
    let lum = |h: &str| -> f32 {
        let v = |i: usize| u8::from_str_radix(&h[i..i + 2], 16).unwrap_or(0) as f32;
        v(1) * 0.299 + v(3) * 0.587 + v(5) * 0.114
    };
    let ink = Hsla::from_str(if lum(hex) > 150.0 { "#141414" } else { "#ffffff" })
        .unwrap_or(theme::ACCENT.dark);
    let ops = fill_ops(&s);
    view()
        .size(px(size))
        .rounded(px(size * 0.3))
        .bg(fill)
        .border(px(1.5))
        .border_color(theme::CARD)
        .items_center()
        .justify_center()
        .child(canvas(move || fill_paths(s.vb, &ops, g, g, ink)).size(px(g)))
        .into_element()
}

/// Brand glyphs are all fills in the brand's color (the TSX ignores `s`).
fn fill_ops(spec: &IconSpec) -> Vec<(Path, FillRule)> {
    spec.paths
        .iter()
        .map(|p| {
            (
                svg_path(p.d),
                if p.evenodd {
                    FillRule::EvenOdd
                } else {
                    FillRule::NonZero
                },
            )
        })
        .collect()
}

fn fill_paths(vb: [f32; 4], ops: &[(Path, FillRule)], w: f32, h: f32, fill: Hsla) -> Painter {
    let mut p = Painter::new()
        .scale(w / vb[2], h / vb[3])
        .translate(-vb[0], -vb[1])
        .fill_style(fill);
    for (path, rule) in ops {
        p = p.fill_path(path, *rule);
    }
    p
}


